import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CFI7Wm0A.js";var i=JSON.parse('{"title":"The RFC Process","description":"Propose a WarpDrive feature or deprecation: discuss it on Discord, draft from rfcs/0000-template.md, open a PR labeled `:label: rfc`, and shepherd it through emberjs/rfcs.","frontmatter":{"title":"The RFC Process","description":"Propose a WarpDrive feature or deprecation: discuss it on Discord, draft from rfcs/0000-template.md, open a PR labeled `:label: rfc`, and shepherd it through emberjs/rfcs."},"headers":[],"relativePath":"guides/contributing/rfc-process.md","filePath":"guides/contributing/rfc-process.md"}'),a={name:`guides/contributing/rfc-process.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h3 id="requesting-features-or-deprecations" tabindex="-1">Requesting Features or Deprecations <a class="header-anchor" href="#requesting-features-or-deprecations" aria-label="Permalink to “Requesting Features or Deprecations”">​</a></h3><p>While WarpDrive is universal in nature, its development is managed by the EmberJS community, and WarpDrive participates in <a href="https://github.com/emberjs/rfcs/" target="_blank" rel="noreferrer">Ember&#39;s RFC process (GitHub emberjs/rfcs)</a>. Most changes to the public API including new features, changes in behavior, or deprecations require community discussion and must go through this process.</p><p><strong>This repository is the source of truth for WarpDrive-specific RFCs.</strong> Drafts live in <a href="/pr-preview/pr-11256/rfcs/"><code>rfcs/</code></a>, iterate as normal PRs against <code>warp-drive-data/warp-drive</code>, and a copy is opened in <code>emberjs/rfcs</code> automatically once the draft merges here — kept in sync in both directions afterward. See the <a href="/pr-preview/pr-11256/skills/contributors/writing-and-implementing-rfcs">Writing and Implementing RFCs</a> skill for the full mechanics (frontmatter fields, the sync bot, numbering). This page covers the process itself.</p><p>While there is no guarantee that an RFC will be accepted, successful RFCs typically follow a pattern of iteration while gathering requirements, addressing feedback, and consensus building. The best RFCs are narrowly scoped with clear understanding of alternatives, drawbacks, and their effect on the community.</p><p>Here are a few suggestions of <strong>steps to take before drafting your RFC</strong> to best make your RFC successful. Often this process will complete quickly, but when it does not, don&#39;t despair! Often the best ideas take the longest to bake.</p><ol><li>Bring up your idea on <a href="https://discord.gg/PHBbnWJx5S" target="_blank" rel="noreferrer">Discord</a> or with individual <a href="https://emberjs.com/team/" target="_blank" rel="noreferrer">team members</a></li><li>Reflect on any concerns, alternatives, or questions that arise from these discussions.</li><li>Continue to discuss the idea, giving time for everyone to digest and think about it.</li><li>Attend the weekly team meeting to discuss your idea</li><li>Open an issue in this repo to broaden and record the discussion if the idea needs more time for discussion and iteration. <ul><li>announce your issue in <code>#dev-ember-data</code> and anywhere else desired such as <code>#news-and-announcements</code> and <code>bluesky</code>.</li></ul></li><li>Draft your RFC in this repo: copy <a href="/pr-preview/pr-11256/rfcs/0000-template"><code>rfcs/0000-template.md</code></a> to the next available <code>rfcs/000N-your-title.md</code> and share it with those you have been discussing the idea with.</li><li>Publish your RFC by opening a PR to <code>warp-drive-data/warp-drive</code> labeled <code>:label: rfc</code><ul><li>announce your PR in <code>#dev-ember-data</code> and anywhere else desired such as <code>#news-and-announcements</code> and <code>bluesky</code>.</li></ul></li><li>Attend weekly team meetings to discuss the RFC, continue iterating on the RFC, and help shepherd it to completion. Once there&#39;s consensus to move forward, merging this PR is what triggers the sync bot to open the mirrored PR in <code>emberjs/rfcs</code>, which is where the formal Ember RFC stages (Proposed, Exploring, Final Comment Period, Accepted, ...) play out — see <a href="https://github.com/emberjs/rfcs#how-it-works" target="_blank" rel="noreferrer">emberjs/rfcs&#39; own process documentation</a> for what happens from there. Stage changes and any edits made upstream during review are synced back into this repo&#39;s copy automatically.</li><li>Build a proof-of-concept. Sometimes this is best if it occurs alongside drafting the RFC, as it often informs the RFC design, known drawbacks, and alternatives. Often it will become incorporated in the final implementation.</li><li>If you are able, help land the work in a release! It is not required that you implement your own RFC but often this is the best way to ensure that accepted RFCs are implemented in a timely manner.</li></ol>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};